training_problem:
Below is the graph of $y = a \sin bx$ for some constants $a < 0$ and $b > 0.$  Find $a.$

[asy]import TrigMacros;

size(400);

real g(real x)
{
	return (-2*sin(x/3));
}

draw(graph(g,-3*pi,3*pi,n=700,join=operator ..),red);
trig_axes(-3*pi,3*pi,-3,3,pi/2,1);
layer();
rm_trig_labels(-5, 5, 2);

label("$1$", (0,1), E);
label("$2$", (0,2), E);
label("$-1$", (0,-1), E);
label("$-2$", (0,-2), E);
[/asy]

benchmark_problem:
Below is the graph of $y = a \sin (bx + c) + d$ for some positive constants $a,$ $b,$ $c,$ and $d.$  Find the smallest possible value of $c.$

[asy]import TrigMacros;

size(400);

real f(real x)
{
	return 2*sin(3*x + pi) + 1;
}

draw(graph(f,-3*pi,3*pi,n=700,join=operator ..),red);
trig_axes(-3*pi,3*pi,-4,4,pi/2,1);
layer();
rm_trig_labels(-5,5, 2);

label("$1$", (0,1), E);
label("$2$", (0,2), E);
label("$3$", (0,3), E);
label("$-1$", (0,-1), E);
label("$-2$", (0,-2), E);
label("$-3$", (0,-3), E);
[/asy]

Find the number of triples of nonnegative integers \((a,b,c)\) satisfying \(a + b + c = 300\) and
\begin{equation*}
a^2b + a^2c + b^2a + b^2c + c^2a + c^2b = 6,000,000.
\end{equation*}

training_problem:
In the diagram below, we have $\sin \angle RPQ = \frac{7}{25}$.  What is $\sin \angle RPS$?

[asy]
pair R,P,Q,SS;
SS = (-2,0);
P = (0,0);
Q = (2,0);
R = rotate(aSin(7/25))*(1.5,0);
dot("$S$",SS,S);
dot("$Q$",Q,S);
dot("$R$",R,N);
dot("$P$",P,S);
draw(Q--SS);
draw(P--R);
[/asy]

benchmark_problem:
In the diagram below, we have $\sin \angle RPQ = \frac{7}{25}$.  What is $\cos \angle RPS$?

[asy]

pair R,P,Q,SS;

SS = (-2,0);

P = (0,0);

Q = (2,0);

R = rotate(aSin(7/25))*(1.5,0);

dot("$S$",SS,S);

dot("$Q$",Q,S);

dot("$R$",R,N);

dot("$P$",P,S);

draw(Q--SS);

draw(P--R);

[/asy]

training_problem:
In the diagram, $D$ and $E$ are the midpoints of $\overline{AB}$ and $\overline{BC}$ respectively.  Determine the area of $\triangle DBC$.

[asy]
size(180); defaultpen(linewidth(.7pt)+fontsize(10pt));
pair A, B, C, D, E, F;
A=(0,6);
B=(0,0);
C=(8,0);
D=(0,3);
E=(4,0);
F=(8/3,2);
draw(E--A--C--D);
draw((-1,0)--(10,0), EndArrow);
draw((0,-1)--(0,8), EndArrow);
label("$A(0,6)$", A, W);
label("$B(0,0)$", B, SW);
label("$C(8,0)$", C, S);
label("$D$", D, W);
label("$E$", E, S);
label("$F$", F, SW);
label("$x$", (10,0), dir(0));
label("$y$", (0,8), dir(90));
[/asy]

